window.TEACH_SLIDES['7-4'] = [{"k": "title", "html": "<p class=\"ts-kicker\">ថ្នាក់ទី ៧ · មេរៀនទី ៤</p><h1>ប្រភាគ</h1><p class=\"ts-sub\">៨ ផ្នែក</p><div class=\"ts-obj\"><h3>គោលបំណង</h3><ol class=\"ts-bullets\"><li>បកស្រាយចំណោទ ដើម្បីបង្ហាញសញ្ញាណប្រភាគនិងប្រភាគសមមូល</li><li>ប្រៀបធៀប រៀបលំដាប់ និងសម្រួលប្រភាគ</li><li>ធ្វើប្រមាណវិធីលើប្រភាគ</li><li>ដោះស្រាយចំណោទដែលទាក់ទងនឹងប្រភាគ ។</li></ol></div>", "c": "cover"}, {"k": "title", "html": "<p class=\"ts-kicker\">ផ្នែក</p><h1>1. សញ្ញាណប្រភាគ</h1>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">1. សញ្ញាណប្រភាគ</p><h2>ឧទាហរណ៍</h2><p>គេកាត់នំមួយជា \\(5\\) ផ្នែកស្មើៗគ្នាចែកឱ្យក្មេង \\(5\\) នាក់ ហើយក្មេងម្នាក់ៗនឹងទទួលបានមួយផ្នែក (មើលរូប) ។ ផ្នែកនីមួយៗស្មើនឹងមួយភាគប្រាំនៃនំ គេសរសេរ \\(\\frac{1}{5}\\) ។</p><p>ប្រភាគជាចំនួនមួយដែលគេសរសេរជាផលចែកនៃមួយចំនួន និងមួយចំនួនផ្សេងទៀតខុសពីសូន្យ ។ ឧទាហរណ៍ ៖ ប្រភាគ \\(\\frac{4}{5}\\) , \\(-\\frac{2}{3}\\) , \\(\\frac{3}{-5}\\) , \\(\\frac{-2}{5}\\) ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">1. សញ្ញាណប្រភាគ</p><h2>ជាទូទៅ</h2><p>\\(\\frac{a}{b}\\) ជាប្រភាគដែល \\(a\\), \\(b\\) ជាចំនួនគត់រ៉ឺឡាទីប ហើយ \\(a\\) ជាភាគយក និង \\(b\\) ជាភាគបែងនៃប្រភាគ (\\(b\\ne0\\)) ។</p>"}, {"k": "title", "html": "<p class=\"ts-kicker\">ផ្នែក</p><h1>2. ប្រភាគសមមូល</h1>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">2. ប្រភាគសមមូល</p><h2>ឧទាហរណ៍ 1</h2><p>សុខ សៅ និងសំបានទិញនំម្នាក់មួយមានទំហំប៉ុនៗគ្នា ។</p><ul class=\"ts-bullets\"><li>សុខកាត់នំជា \\(3\\) ចំណែកស្មើៗគ្នា ហើយបានញ៉ាំអស់ \\(1\\) ចំណែក ។ គេថាសុខបានញ៉ាំអស់ \\(\\frac{1}{3}\\) នៃនំនោះ ។</li><li>សៅកាត់នំជា \\(6\\) ចំណែកស្មើៗគ្នា ហើយបានញ៉ាំអស់ \\(2\\) ចំណែក ។ គេថាសៅបានញ៉ាំអស់ \\(\\frac{2}{6}\\) នៃនំនោះ ។</li><li>សំកាត់នំជា \\(9\\) ចំណែកស្មើៗគ្នា ហើយបានញ៉ាំអស់ \\(3\\) ចំណែក ។ គេថាសំបានញ៉ាំអស់ \\(\\frac{3}{9}\\) នៃនំនោះ ។</li></ul><p>\\(\\frac{1}{3}\\) , \\(\\frac{2}{6}\\) និង \\(\\frac{3}{9}\\) គឺតាងបរិមាណស្មើគ្នា ជាប្រភាគសមមូល ។ គេសរសេរ \\[\\frac{1}{3}=\\frac{2}{6}=\\frac{3}{9}\\] គេសម្គាល់ឃើញថា \\[\\frac{1}{3}=\\frac{2}{6} \\text{ ហើយ } 1\\times6=3\\times2\\] \\[\\frac{2}{6}=\\frac{3}{9} \\text{ ហើយ } 2\\times9=6\\times3\\]</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">2. ប្រភាគសមមូល</p><h2>ឧទាហរណ៍ 2</h2><ul class=\"ts-bullets\"><li>\\(\\frac{-3}{4}=\\frac{6}{-8}\\) ព្រោះ \\((-3)\\times(-8)=4\\times6=24\\)</li><li>\\(\\frac{3}{7}\\ne\\frac{-4}{5}\\) ព្រោះ \\(3\\times5\\ne7\\times(-4)\\) ។</li></ul>"}, {"k": "key", "html": "<p class=\"ts-kicker\">2. ប្រភាគសមមូល</p><h2>ជាទូទៅ</h2><p>ប្រភាគសមមូល ជាប្រភាគតាងឱ្យបរិមាណស្មើគ្នា ។ បើប្រភាគ \\(\\frac{a}{b}\\) និង \\(\\frac{c}{d}\\) ជាប្រភាគសមមូល មានន័យថា \\(\\frac{a}{b}=\\frac{c}{d}\\) លុះត្រាតែ \\(a\\times d=b\\times c\\) ដែល \\(b\\ne0\\), \\(d\\ne0\\) ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">2. ប្រភាគសមមូល</p><h2>សម្គាល់</h2><p>\\[\\frac{1}{3}=\\frac{1\\times2}{3\\times2}=\\frac{2}{6}, \\qquad \\frac{2}{6}=\\frac{2\\div2}{6\\div2}=\\frac{1}{3}\\] \\[\\frac{3}{-5}=\\frac{3\\times(-1)}{(-5)\\times(-1)}=\\frac{-3}{5}, \\qquad \\frac{-3}{9}=\\frac{(-3)\\div3}{9\\div3}=\\frac{-1}{3}\\] ដូច្នេះតម្លៃនៃប្រភាគមិនប្រែប្រួលទេ បើគេគុណឬចែកភាគយកនិងភាគបែងនៃប្រភាគនោះនឹងមួយចំនួនខុសពីសូន្យ មានន័យថា \\[\\frac{a}{b}=\\frac{a\\times c}{b\\times c} \\qquad \\text{និង} \\qquad \\frac{a}{b}=\\frac{a\\div c}{b\\div c} \\qquad (c\\ne0)\\]</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2. ប្រភាគសមមូល</p><h2>លំហាត់គំរូ</h2><p>រកតម្លៃ \\(x\\) បើគេដឹងថា \\(\\frac{x}{4}=\\frac{21}{28}\\) ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2. ប្រភាគសមមូល</p><h2>ដំណោះស្រាយ</h2><p>\\[\\begin{aligned}\n\\frac{x}{4} &amp;= \\frac{21}{28} \\\\\nx\\times28 &amp;= 4\\times21 \\\\\nx &amp;= \\frac{4\\times21}{28} \\\\\n  &amp;= 3\n\\end{aligned}\\] ដូចនេះ \\(x=3\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">2. ប្រភាគសមមូល</p><h2>ប្រតិបត្តិ</h2><p>បំពេញចំនួនក្នុងប្រអប់</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(\\frac{2}{7}=\\frac{4}{\\square}\\)</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(\\frac{-15}{25}=\\frac{\\square}{5}\\)</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>\\(\\frac{4}{9}=\\frac{28}{\\square}\\) ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">2. ប្រភាគសមមូល</p><h2>ចម្លើយ</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>ពី \\(2\\) ទៅ \\(4\\) គឺគុណនឹង \\(2\\) ដូចនេះភាគបែងក៏គុណនឹង \\(2\\) ដែរ ៖ \\[\\frac{2}{7}=\\frac{2\\times2}{7\\times2}=\\frac{4}{14} \\implies \\square=14\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>ពី \\(25\\) ទៅ \\(5\\) គឺចែកនឹង \\(5\\) ដូចនេះភាគយកក៏ចែកនឹង \\(5\\) ដែរ ៖ \\[\\frac{-15}{25}=\\frac{-15\\div5}{25\\div5}=\\frac{-3}{5} \\implies \\square=-3\\]</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>ពី \\(4\\) ទៅ \\(28\\) គឺគុណនឹង \\(7\\) ដូចនេះភាគបែងក៏គុណនឹង \\(7\\) ដែរ ៖ \\[\\frac{4}{9}=\\frac{4\\times7}{9\\times7}=\\frac{28}{63} \\implies \\square=63\\]</div></li></ul><p>ដូចនេះ ក. \\(14\\) ខ. \\(-3\\) គ. \\(63\\) ។</p>"}, {"k": "title", "html": "<p class=\"ts-kicker\">ផ្នែក</p><h1>3. ការសម្រួលប្រភាគ</h1>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">3. ការសម្រួលប្រភាគ</p><h2>ឧទាហរណ៍</h2><p>សម្រួលប្រភាគ \\(\\frac{6}{15}\\) ។ \\(6\\) និង \\(15\\) មានតួចែករួមស្មើនឹង \\(3\\) ៖ នោះ \\[\\frac{6}{15}=\\frac{3\\times2}{3\\times5}=\\frac{2}{5} \\qquad \\text{ឬ} \\qquad \\frac{6}{15}=\\frac{6\\div3}{15\\div3}=\\frac{2}{5}\\] \\(\\frac{2}{5}\\) ជាប្រភាគបង្រួមមិនបាន ហើយស្មើគ្នានឹង \\(\\frac{6}{15}\\) ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">3. ការសម្រួលប្រភាគ</p><h2>ជាទូទៅ</h2><ol class=\"ts-bullets\"><li>ការសម្រួលប្រភាគ គឺធ្វើឱ្យប្រភាគនោះទៅជាប្រភាគបង្រួមមិនបានដែលសមមូលនឹងវា ។</li><li>ការសម្រួលប្រភាគអាចចែកភាគយកនិងភាគបែងនៃប្រភាគនោះនឹងតួចែករួមធំបំផុតនៃភាគយកនិងភាគបែង ។</li><li>\\(\\frac{a}{b}\\) ជាប្រភាគ ហើយ \\(k\\) ជាចំនួនមួយខុសពី \\(0\\) គេបាន \\(\\frac{ka}{kb}=\\frac{a}{b}\\) ។</li></ol>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">3. ការសម្រួលប្រភាគ</p><h2>លំហាត់គំរូ</h2><p>សម្រួលប្រភាគ</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(\\frac{16}{40}\\) និង \\(\\frac{70}{245}\\)</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(\\frac{18}{-33}\\) និង \\(\\frac{-36}{-12}\\) ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">3. ការសម្រួលប្រភាគ</p><h2>ដំណោះស្រាយ</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គេបាន ៖ \\[\\frac{16}{40}=\\frac{16\\div8}{40\\div8}=\\frac{2}{5}\\] \\[\\frac{70}{245}=\\frac{70\\div35}{245\\div35}=\\frac{2}{7}\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>គេបាន ៖ \\[\\frac{18}{-33}=\\frac{18\\div3}{(-33)\\div3}=\\frac{6}{-11}\\] \\[\\frac{-36}{-12}=\\frac{36}{12}=\\frac{36\\div12}{12\\div12}=\\frac{3}{1}=3\\]</div></li></ul>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">3. ការសម្រួលប្រភាគ</p><h2>ប្រតិបត្តិ</h2><p>សម្រួលប្រភាគ \\(\\frac{18}{30}\\), \\(\\frac{-19}{57}\\) និង \\(\\frac{-10}{-15}\\) ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">3. ការសម្រួលប្រភាគ</p><h2>ចម្លើយ</h2><p>\\[\\frac{18}{30}=\\frac{18\\div6}{30\\div6}=\\frac{3}{5}\\] \\[\\frac{-19}{57}=\\frac{(-19)\\div19}{57\\div19}=\\frac{-1}{3}\\] \\[\\frac{-10}{-15}=\\frac{10}{15}=\\frac{10\\div5}{15\\div5}=\\frac{2}{3}\\] ដូចនេះ \\(\\frac{3}{5}\\), \\(\\frac{-1}{3}\\) និង \\(\\frac{2}{3}\\) ។</p>"}, {"k": "title", "html": "<p class=\"ts-kicker\">ផ្នែក</p><h1>4. ការប្រៀបធៀបនិងរៀបលំដាប់ប្រភាគ</h1>"}, {"k": "", "html": "<p class=\"ts-kicker\">ផ្នែក</p><h2>4. ការប្រៀបធៀបនិងរៀបលំដាប់ប្រភាគ</h2><p>ករណីភាគបែងដូចគ្នា គេប្រៀបធៀបតែភាគយក ។</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">4. ការប្រៀបធៀបនិងរៀបលំដាប់ប្រភាគ</p><h2>ឧទាហរណ៍</h2><p class=\"ts-exh\">ឧទាហរណ៍ 1</p><ul class=\"ts-bullets\"><li>\\(\\frac{2}{5}&lt;\\frac{4}{5}\\) ព្រោះ \\(2&lt;4\\)</li><li>\\(\\frac{9}{11}&gt;\\frac{3}{11}\\) ព្រោះ \\(9&gt;3\\)</li><li>\\(\\frac{-3}{4}&lt;\\frac{-1}{4}\\) ព្រោះ \\(-3&lt;-1\\)</li><li>\\(\\frac{2}{5}&gt;\\frac{-4}{5}\\) ព្រោះ \\(2&gt;-4\\) ។</li></ul><p>ករណីភាគបែងខុសគ្នា គេតម្រូវភាគបែងរួមរួចហើយគេប្រៀបធៀបតែភាគយក ។</p><p class=\"ts-exh\">ឧទាហរណ៍ 2</p><p>ប្រៀបធៀបនិងរៀបប្រភាគ \\(\\frac{2}{3}\\), \\(\\frac{1}{2}\\), \\(\\frac{3}{8}\\) និង \\(\\frac{5}{6}\\) តាមលំដាប់ចុះ ។</p><p>ពហុគុណរួមតូចបំផុតនៃភាគបែង \\(3, 2, 8\\) និង \\(6\\) ស្មើនឹង \\(24\\) ។ បន្ទាប់មកគេប្តូរប្រភាគនីមួយៗទៅជាប្រភាគសមមូលដែលមានភាគបែងស្មើនឹង \\(24\\) ៖ \\[\\begin{aligned}\n\\frac{2}{3} &amp;= \\frac{2\\times8}{3\\times8} = \\frac{16}{24} \\\\\n\\frac{1}{2} &amp;= \\frac{1\\times12}{2\\times12} = \\frac{12}{24} \\\\\n\\frac{3}{8} &amp;= \\frac{3\\times3}{8\\times3} = \\frac{9}{24} \\\\\n\\frac{5}{6} &amp;= \\frac{5\\times4}{6\\times4} = \\frac{20}{24}\n\\end{aligned}\\] គេបាន \\(\\frac{20}{24}&gt;\\frac{16}{24}&gt;\\frac{12}{24}&gt;\\frac{9}{24}\\) ។</p><p>ដោយរៀបតាមលំដាប់ចុះ គេបាន \\(\\frac{5}{6}\\), \\(\\frac{2}{3}\\), \\(\\frac{1}{2}\\), \\(\\frac{3}{8}\\) ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">4. ការប្រៀបធៀបនិងរៀបលំដាប់ប្រភាគ</p><h2>ជាទូទៅ</h2><ol class=\"ts-bullets\"><li>ដើម្បីប្រៀបធៀបប្រភាគដែលមានភាគបែងដូចគ្នា គេប្រៀបធៀបតែភាគយក ។</li><li>ដើម្បីប្រៀបធៀបប្រភាគដែលមានភាគបែងខុសគ្នា គេត្រូវតម្រូវភាគបែងរួមរួចហើយប្រៀបធៀបភាគយកនិងភាគយក ។</li></ol>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">4. ការប្រៀបធៀបនិងរៀបលំដាប់ប្រភាគ</p><h2>លំហាត់គំរូ 1</h2><p>ប្រៀបធៀបនិងរៀបលំដាប់ប្រភាគ \\(\\frac{11}{12}\\), \\(\\frac{5}{8}\\), \\(\\frac{7}{9}\\) និង \\(\\frac{3}{4}\\) តាមលំដាប់ឡើង ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">4. ការប្រៀបធៀបនិងរៀបលំដាប់ប្រភាគ</p><h2>ដំណោះស្រាយ</h2><p>ពហុគុណរួមតូចបំផុតនៃ \\(12, 8, 9\\) និង \\(4\\) ស្មើនឹង \\(72\\) ។ \\[\\begin{aligned}\n\\frac{11}{12} &amp;= \\frac{11\\times6}{12\\times6} = \\frac{66}{72} \\\\\n\\frac{5}{8} &amp;= \\frac{5\\times9}{8\\times9} = \\frac{45}{72} \\\\\n\\frac{7}{9} &amp;= \\frac{7\\times8}{9\\times8} = \\frac{56}{72} \\\\\n\\frac{3}{4} &amp;= \\frac{3\\times18}{4\\times18} = \\frac{54}{72}\n\\end{aligned}\\] គេបាន \\(\\frac{45}{72}&lt;\\frac{54}{72}&lt;\\frac{56}{72}&lt;\\frac{66}{72}\\) ។</p><p>ដូចនេះ ដោយរៀបតាមលំដាប់ឡើង គេបាន \\(\\frac{5}{8}\\), \\(\\frac{3}{4}\\), \\(\\frac{7}{9}\\), \\(\\frac{11}{12}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">4. ការប្រៀបធៀបនិងរៀបលំដាប់ប្រភាគ</p><h2>លំហាត់គំរូ 2</h2><p>ប្រៀបធៀបប្រភាគ \\(\\frac{-3}{4}\\) និង \\(\\frac{4}{-5}\\) ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">4. ការប្រៀបធៀបនិងរៀបលំដាប់ប្រភាគ</p><h2>ដំណោះស្រាយ</h2><p>ប្រភាគ \\(\\frac{-3}{4}\\) និង \\(\\frac{4}{-5}=\\frac{-4}{5}\\) មានភាគបែងរួមស្មើនឹង \\(20\\) ។ \\[\\begin{aligned}\n\\frac{-3}{4} &amp;= \\frac{(-3)\\times5}{4\\times5} = \\frac{-15}{20} \\\\\n\\frac{-4}{5} &amp;= \\frac{(-4)\\times4}{5\\times4} = \\frac{-16}{20}\n\\end{aligned}\\] ដោយ \\(-15&gt;-16\\) នាំឱ្យ \\(\\frac{-15}{20}&gt;\\frac{-16}{20}\\) ។</p><p>ដូចនេះ \\(\\frac{-3}{4}&gt;\\frac{-4}{5}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">4. ការប្រៀបធៀបនិងរៀបលំដាប់ប្រភាគ</p><h2>ប្រតិបត្តិ</h2><p>ប្រៀបធៀបប្រភាគ</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(\\frac{24}{60}\\), \\(\\frac{26}{30}\\) និង \\(\\frac{27}{45}\\)</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(\\frac{-11}{12}\\), \\(\\frac{17}{-18}\\) និង \\(\\frac{-9}{25}\\) ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">4. ការប្រៀបធៀបនិងរៀបលំដាប់ប្រភាគ</p><h2>ចម្លើយ</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>ពហុគុណរួមតូចបំផុតនៃ \\(60, 30\\) និង \\(45\\) ស្មើនឹង \\(180\\) ៖ \\[\\frac{24}{60}=\\frac{72}{180}, \\qquad \\frac{26}{30}=\\frac{156}{180}, \\qquad \\frac{27}{45}=\\frac{108}{180}\\] ដោយ \\(156&gt;108&gt;72\\) នោះ \\(\\frac{26}{30}&gt;\\frac{27}{45}&gt;\\frac{24}{60}\\) ។</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>គេមាន \\(\\frac{17}{-18}=\\frac{-17}{18}\\) ។ ពហុគុណរួមតូចបំផុតនៃ \\(12, 18\\) និង \\(25\\) ស្មើនឹង \\(900\\) ៖ \\[\\frac{-11}{12}=\\frac{-825}{900}, \\qquad \\frac{-17}{18}=\\frac{-850}{900}, \\qquad \\frac{-9}{25}=\\frac{-324}{900}\\] ដោយ \\(-324&gt;-825&gt;-850\\) នោះ \\(\\frac{-9}{25}&gt;\\frac{-11}{12}&gt;\\frac{17}{-18}\\) ។</div></li></ul>"}, {"k": "title", "html": "<p class=\"ts-kicker\">ផ្នែក</p><h1>5. វិធីបូកនិងដកប្រភាគ</h1>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">5. វិធីបូកនិងដកប្រភាគ · 5.1. វិធីបូកប្រភាគមានភាគបែងដូចគ្នា</p><h2>ឧទាហរណ៍</h2><p class=\"ts-exh\">ឧទាហរណ៍ 1</p><p>គណនា \\(\\frac{2}{7}+\\frac{3}{7}\\) ។ តាមរូបបង្ហាញថា \\[\\frac{2}{7}+\\frac{3}{7}=\\frac{2+3}{7}=\\frac{5}{7}\\]</p><p class=\"ts-exh\">ឧទាហរណ៍ 2</p><p>\\[\\frac{-3}{5}+\\frac{1}{5}=\\frac{-3+1}{5}=\\frac{-2}{5}\\] \\[\\frac{2}{9}+\\frac{7}{-9}=\\frac{2}{9}+\\frac{-7}{9}=\\frac{2+(-7)}{9}=\\frac{-5}{9} \\qquad \\left(\\text{ដោយ } \\frac{7}{-9}=\\frac{-7}{9}\\right)\\]</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">5. វិធីបូកនិងដកប្រភាគ · 5.1. វិធីបូកប្រភាគមានភាគបែងដូចគ្នា</p><h2>ជាទូទៅ</h2><p>ដើម្បីបូកប្រភាគដែលមានភាគបែងដូចគ្នា គេបូកតែភាគយករក្សាភាគបែងទុកដដែល \\[\\frac{a}{c}+\\frac{b}{c}=\\frac{a+b}{c}\\] ដែល \\(a\\), \\(b\\), \\(c\\) ជាចំនួនគត់រ៉ឺឡាទីប ហើយ \\(c\\ne0\\) ។</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">5. វិធីបូកនិងដកប្រភាគ · 5.2. វិធីបូកប្រភាគមានភាគបែងខុសគ្នា</p><h2>ឧទាហរណ៍</h2><p class=\"ts-exh\">ឧទាហរណ៍ 1</p><p>គណនា \\(\\frac{1}{3}+\\frac{1}{4}\\)</p><p>\\[\\frac{1}{3}+\\frac{1}{4}=\\frac{4}{12}+\\frac{3}{12}=\\frac{7}{12}\\] (តម្រូវភាគបែងរួមតូចបំផុតដែលស្មើនឹង \\(\\text{LCM}(3,4)=12\\)) ។</p><p class=\"ts-exh\">ឧទាហរណ៍ 2</p><p>\\[\\frac{2}{3}+\\frac{-3}{5}=\\frac{10}{15}+\\frac{-9}{15}=\\frac{10+(-9)}{15}=\\frac{1}{15}\\] (តម្រូវភាគបែងរួមតូចបំផុតដែលស្មើនឹង \\(\\text{LCM}(3,5)=15\\)) ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">5. វិធីបូកនិងដកប្រភាគ · 5.2. វិធីបូកប្រភាគមានភាគបែងខុសគ្នា</p><h2>ជាទូទៅ</h2><p>ដើម្បីបូកប្រភាគដែលមានភាគបែងខុសគ្នា គេត្រូវតម្រូវភាគបែងរួម (គេយក LCM នៃភាគបែងជាភាគបែងរួម) រួចគេបូកភាគយកនិងភាគយក ហើយរក្សាភាគបែងរួមទុកដដែល ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">5. វិធីបូកនិងដកប្រភាគ · 5.2. វិធីបូកប្រភាគមានភាគបែងខុសគ្នា</p><h2>លក្ខណៈ</h2><ol class=\"ts-bullets\"><li>\\(\\frac{a}{b}+\\frac{c}{d}=\\frac{c}{d}+\\frac{a}{b}\\) លក្ខណៈត្រឡប់</li><li>\\(\\left(\\frac{a}{b}+\\frac{c}{d}\\right)+\\frac{p}{q}=\\frac{a}{b}+\\left(\\frac{c}{d}+\\frac{p}{q}\\right)\\) លក្ខណៈផ្តុំ</li><li>\\(\\frac{a}{b}+0=0+\\frac{a}{b}=\\frac{a}{b}\\)</li></ol>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">5. វិធីបូកនិងដកប្រភាគ · 5.3. វិធីដកប្រភាគមានភាគបែងដូចគ្នា</p><h2>ឧទាហរណ៍</h2><p class=\"ts-exh\">ឧទាហរណ៍ 1</p><p>គណនា \\(\\frac{6}{7}-\\frac{2}{7}\\) ។ តាមរូបបង្ហាញថា \\[\\frac{6}{7}-\\frac{2}{7}=\\frac{4}{7}\\]</p><p>ដូចនេះ \\[\\frac{6}{7}-\\frac{2}{7}=\\frac{6-2}{7}=\\frac{4}{7}\\]</p><p class=\"ts-exh\">ឧទាហរណ៍ 2</p><p>\\[\\frac{-3}{5}-\\frac{1}{5}=\\frac{-3-1}{5}=\\frac{-4}{5}\\]</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">5. វិធីបូកនិងដកប្រភាគ · 5.3. វិធីដកប្រភាគមានភាគបែងដូចគ្នា</p><h2>ជាទូទៅ</h2><p>\\[\\frac{a}{c}-\\frac{b}{c}=\\frac{a-b}{c}\\] ដែល \\(a, b, c\\) ជាចំនួនគត់រ៉ឺឡាទីប \\(c\\ne0\\) ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">5. វិធីបូកនិងដកប្រភាគ · 5.3. វិធីដកប្រភាគមានភាគបែងដូចគ្នា</p><h2>សម្គាល់</h2><p>គេថាប្រភាគ \\(-\\frac{3}{5}\\) ផ្ទុយគ្នានឹងប្រភាគ \\(\\frac{3}{5}\\) ព្រោះ \\(\\frac{3}{5}+\\left(-\\frac{3}{5}\\right)=0\\) និង \\(\\frac{-3}{5}=-\\frac{3}{5}\\) ។</p><p>ដូច្នេះ បើប្រភាគ \\(\\frac{a}{b}\\) ផ្ទុយគ្នានឹង \\(-\\frac{a}{b}\\) គេបាន \\(\\frac{a}{b}+\\left(-\\frac{a}{b}\\right)=0\\) ហើយ \\[-\\frac{a}{b}=\\frac{a}{-b}=\\frac{-a}{b}\\]</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">5. វិធីបូកនិងដកប្រភាគ · 5.4. វិធីដកប្រភាគមានភាគបែងខុសគ្នា</p><h2>ឧទាហរណ៍</h2><p class=\"ts-exh\">ឧទាហរណ៍ 1</p><p>គណនា \\(\\frac{7}{8}-\\frac{1}{2}\\) ។ តាមរូបបង្ហាញថា</p><p>\\[\\frac{7}{8}-\\frac{1}{2}=\\frac{7}{8}-\\frac{4}{8}=\\frac{3}{8}\\] ប្រភាគទាំងពីរមានភាគបែងរួម \\(\\text{LCM}(8,2)=8\\) ។</p><p class=\"ts-exh\">ឧទាហរណ៍ 2</p><p>\\[\\frac{2}{7}-\\left(-\\frac{1}{4}\\right)=\\frac{2}{7}+\\frac{1}{4}=\\frac{8+7}{28}=\\frac{15}{28}\\] (ភាគបែងរួម \\(\\text{LCM}(7,4)=28\\)) ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">5. វិធីបូកនិងដកប្រភាគ · 5.4. វិធីដកប្រភាគមានភាគបែងខុសគ្នា</p><h2>ជាទូទៅ</h2><p>ដើម្បីដកប្រភាគដែលមានភាគបែងខុសគ្នា គេត្រូវតម្រូវភាគបែងរួម (គេយក LCM នៃភាគបែងជាភាគបែងរួម) រួចគេដកភាគយកនិងភាគយក ហើយរក្សាភាគបែងរួមទុកដដែល ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">5. វិធីបូកនិងដកប្រភាគ · 5.4. វិធីដកប្រភាគមានភាគបែងខុសគ្នា</p><h2>លំហាត់គំរូ</h2><p>គណនា \\(x\\) ដោយដឹងថា \\(\\frac{x}{5}=\\frac{5}{6}+\\frac{-19}{30}\\) ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">5. វិធីបូកនិងដកប្រភាគ · 5.4. វិធីដកប្រភាគមានភាគបែងខុសគ្នា</p><h2>ដំណោះស្រាយ</h2><p>\\[\\begin{aligned}\n\\frac{x}{5} &amp;= \\frac{5}{6}+\\frac{-19}{30} \\\\\n &amp;= \\frac{25-19}{30} \\\\\n &amp;= \\frac{6}{30} \\\\\n &amp;= \\frac{1}{5}\n\\end{aligned}\\] ដូច្នេះ \\(\\frac{x}{5}=\\frac{1}{5}\\) នាំឱ្យ \\(x=1\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">5. វិធីបូកនិងដកប្រភាគ · 5.4. វិធីដកប្រភាគមានភាគបែងខុសគ្នា</p><h2>ប្រតិបត្តិ</h2><p>គណនាកន្សោម \\[A=-\\frac{1}{2}-\\frac{1}{4}-\\left(-\\frac{9}{10}\\right) \\qquad \\text{និង} \\qquad B=\\frac{3}{14}-\\frac{5}{-8}+\\frac{-1}{2}\\]</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">5. វិធីបូកនិងដកប្រភាគ · 5.4. វិធីដកប្រភាគមានភាគបែងខុសគ្នា</p><h2>ចម្លើយ</h2><p>\\[\\begin{aligned}\nA &amp;= -\\frac{1}{2}-\\frac{1}{4}+\\frac{9}{10} \\\\\n  &amp;= \\frac{-10}{20}-\\frac{5}{20}+\\frac{18}{20} \\\\\n  &amp;= \\frac{-10-5+18}{20} \\\\\n  &amp;= \\frac{3}{20}\n\\end{aligned}\\] \\[\\begin{aligned}\nB &amp;= \\frac{3}{14}+\\frac{5}{8}-\\frac{1}{2} \\\\\n  &amp;= \\frac{12}{56}+\\frac{35}{56}-\\frac{28}{56} \\\\\n  &amp;= \\frac{12+35-28}{56} \\\\\n  &amp;= \\frac{19}{56}\n\\end{aligned}\\] ដូចនេះ \\(A=\\frac{3}{20}\\) និង \\(B=\\frac{19}{56}\\) ។</p>"}, {"k": "title", "html": "<p class=\"ts-kicker\">ផ្នែក</p><h1>6. វិធីគុណប្រភាគ</h1>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">6. វិធីគុណប្រភាគ</p><h2>ឧទាហរណ៍</h2><p class=\"ts-exh\">ឧទាហរណ៍ 1</p><p>គណនា \\(\\frac{1}{2}\\times\\frac{1}{4}\\) ។</p><p>\\(\\frac{1}{2}\\times\\frac{1}{4}\\) មានន័យថា \\(\\frac{1}{2}\\) នៃ \\(\\frac{1}{4}\\) ។ គេត្រូវចែក \\(\\frac{1}{4}\\) ជា \\(2\\) ផ្នែកស្មើគ្នា រួចហើយយក \\(1\\) ផ្នែក ។</p><p>តាមរូបបង្ហាញថា \\[\\frac{1}{2}\\times\\frac{1}{4}=\\frac{1\\times1}{2\\times4}=\\frac{1}{8}\\]</p><p class=\"ts-exh\">ឧទាហរណ៍ 2</p><p>\\[\\frac{-3}{7}\\times\\frac{2}{-5}=\\frac{(-3)\\times2}{7\\times(-5)}=\\frac{-6}{-35}=\\frac{6}{35}\\]</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">6. វិធីគុណប្រភាគ</p><h2>ជាទូទៅ</h2><p>ដើម្បីគុណប្រភាគ \\(\\frac{a}{b}\\) និង \\(\\frac{c}{d}\\) គេគុណភាគយកនិងភាគយក ហើយគុណភាគបែងនិងភាគបែង គេបាន \\[\\frac{a}{b}\\times\\frac{c}{d}=\\frac{a\\times c}{b\\times d}\\] ដែល \\(b\\ne0\\) និង \\(d\\ne0\\) ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">6. វិធីគុណប្រភាគ</p><h2>សម្គាល់</h2><ol class=\"ts-bullets\"><li>បើ \\(d=1\\) គេបាន \\(\\frac{a}{b}\\times c=\\frac{a\\times c}{b}\\)</li><li>\\(\\frac{a}{b}\\times\\frac{c}{d}=\\frac{c}{d}\\times\\frac{a}{b}\\)</li><li>\\(\\left(\\frac{a}{b}\\times\\frac{c}{d}\\right)\\times\\frac{p}{q}=\\frac{a}{b}\\times\\left(\\frac{c}{d}\\times\\frac{p}{q}\\right)\\)</li><li>\\(\\frac{a}{b}\\times1=1\\times\\frac{a}{b}=\\frac{a}{b}\\)</li><li>\\(\\frac{a}{b}\\times\\left(\\frac{c}{d}+\\frac{p}{q}\\right)=\\frac{a}{b}\\times\\frac{c}{d}+\\frac{a}{b}\\times\\frac{p}{q}\\)</li></ol>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">6. វិធីគុណប្រភាគ</p><h2>លំហាត់គំរូ</h2><p>គណនា \\[A=\\frac{5}{7}\\times\\frac{8}{15}\\times\\frac{14}{3} \\qquad \\text{និង} \\qquad B=\\frac{-7}{15}\\times\\frac{5}{8}\\times\\frac{15}{-7}\\times(-16)\\]</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">6. វិធីគុណប្រភាគ</p><h2>ដំណោះស្រាយ</h2><p>\\[\\begin{aligned}\nA &amp;= \\frac{5}{7}\\times\\frac{8}{15}\\times\\frac{14}{3} \\\\\n  &amp;= \\frac{5\\times8\\times14}{7\\times15\\times3} \\\\\n  &amp;= \\frac{1\\times8\\times2}{1\\times3\\times3} \\\\\n  &amp;= \\frac{16}{9} = 1\\frac{7}{9}\n\\end{aligned}\\] \\[\\begin{aligned}\nB &amp;= \\frac{-7}{15}\\times\\frac{5}{8}\\times\\frac{15}{-7}\\times(-16) \\\\\n  &amp;= \\left(\\frac{-7}{15}\\times\\frac{15}{-7}\\right)\\times\\left(\\frac{5}{8}\\times(-16)\\right) \\\\\n  &amp;= 1\\times(-10) \\\\\n  &amp;= -10\n\\end{aligned}\\] ដូច្នេះ \\(A=1\\frac{7}{9}\\) និង \\(B=-10\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">6. វិធីគុណប្រភាគ</p><h2>ប្រតិបត្តិ</h2><p>គណនា \\[A=\\frac{-15}{9}\\times\\frac{13}{28}-\\frac{13}{28}\\times\\frac{4}{9}, \\qquad B=-3\\frac{1}{4}\\times1\\frac{3}{5}\\times\\left(-1\\frac{2}{13}\\right)\\]</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">6. វិធីគុណប្រភាគ</p><h2>ចម្លើយ</h2><p>\\[\\begin{aligned}\nA &amp;= \\frac{13}{28}\\times\\left(\\frac{-15}{9}-\\frac{4}{9}\\right) \\\\\n  &amp;= \\frac{13}{28}\\times\\frac{-19}{9} \\\\\n  &amp;= \\frac{-247}{252}\n\\end{aligned}\\] \\[\\begin{aligned}\nB &amp;= \\frac{-13}{4}\\times\\frac{8}{5}\\times\\frac{-15}{13} \\\\\n  &amp;= \\frac{13\\times8\\times15}{4\\times5\\times13} \\\\\n  &amp;= 6\n\\end{aligned}\\] ដូចនេះ \\(A=\\frac{-247}{252}\\) និង \\(B=6\\) ។</p>"}, {"k": "title", "html": "<p class=\"ts-kicker\">ផ្នែក</p><h1>7. វិធីចែកប្រភាគ</h1>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">7. វិធីចែកប្រភាគ</p><h2>ឧទាហរណ៍</h2><p class=\"ts-exh\">ឧទាហរណ៍ 1</p><p>គណនា \\(\\frac{3}{5}\\div\\frac{1}{10}\\) ។</p><p>គេអាចសួរថា “តើគេអាចដក \\(\\frac{1}{10}\\) ចេញពី \\(\\frac{3}{5}\\) បានប៉ុន្មានដង?” តាមរូបបង្ហាញឱ្យឃើញថា គេអាចដក \\(\\frac{1}{10}\\) បានដល់ទៅ \\(6\\) ដងចេញពី \\(\\frac{3}{5}\\) ។</p><p>\\[\\frac{3}{5}\\div\\frac{1}{10}=6 \\qquad \\text{ប៉ុន្តែ} \\qquad \\frac{3}{5}\\times\\frac{10}{1}=6\\] ដូច្នេះ \\(\\frac{3}{5}\\div\\frac{1}{10}=\\frac{3}{5}\\times\\frac{10}{1}\\) ។</p><p class=\"ts-exh\">ឧទាហរណ៍ 2</p><p>គណនា \\(\\frac{-3}{4}\\div2\\) តាមលទ្ធផលខាងលើ \\[\\frac{-3}{4}\\div2=\\frac{-3}{4}\\div\\frac{2}{1}=\\frac{-3}{4}\\times\\frac{1}{2}=\\frac{-3}{8}\\]</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">7. វិធីចែកប្រភាគ</p><h2>ជាទូទៅ</h2><p>ដើម្បីចែកប្រភាគនិងប្រភាគ គេត្រូវយកប្រភាគទី \\(1\\) គុណនឹងចម្រាសនៃប្រភាគទី \\(2\\) ។ ចំពោះប្រភាគ \\(\\frac{a}{b}\\) និង \\(\\frac{c}{d}\\) ដែល \\(b\\ne0\\), \\(c\\ne0\\), \\(d\\ne0\\) គេបាន \\[\\frac{a}{b}\\div\\frac{c}{d}=\\frac{a}{b}\\times\\frac{d}{c}=\\frac{ad}{bc}, \\qquad a\\div\\frac{c}{d}=a\\times\\frac{d}{c}=\\frac{a\\times d}{c} \\quad (c\\ne0)\\]</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">7. វិធីចែកប្រភាគ</p><h2>សម្គាល់</h2><p>ចម្រាសនៃ \\(2\\) គឺ \\(\\frac{1}{2}\\) ចម្រាសនៃ \\(\\frac{1}{3}\\) គឺ \\(3\\) និងចម្រាសនៃ \\(-\\frac{2}{5}\\) គឺ \\(-\\frac{5}{2}\\) ។</p>"}, {"k": "key", "html": "<p class=\"ts-kicker\">7. វិធីចែកប្រភាគ</p><h2>ជាទូទៅ</h2><p>ចម្រាសនៃ \\(a\\) គឺ \\(\\frac{1}{a}\\) និងចម្រាសនៃ \\(\\frac{a}{b}\\) គឺ \\(\\frac{b}{a}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">7. វិធីចែកប្រភាគ</p><h2>លំហាត់គំរូ</h2><p>គណនាកន្សោម \\(A=\\left(\\frac{1}{5}-\\frac{1}{2}\\right)\\div\\left(-\\frac{2}{3}\\times\\frac{1}{8}\\right)\\) ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">7. វិធីចែកប្រភាគ</p><h2>ដំណោះស្រាយ</h2><p>\\[\\begin{aligned}\nA &amp;= \\left(\\frac{1}{5}-\\frac{1}{2}\\right)\\div\\left(-\\frac{2}{3}\\times\\frac{1}{8}\\right) \\\\\n  &amp;= \\left(\\frac{2-5}{10}\\right)\\div\\left(-\\frac{1}{12}\\right) \\\\\n  &amp;= \\left(-\\frac{3}{10}\\right)\\times\\left(-\\frac{12}{1}\\right) \\\\\n  &amp;= \\frac{18}{5} = 3\\frac{3}{5}\n\\end{aligned}\\] ដូច្នេះ \\(A=3\\frac{3}{5}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">7. វិធីចែកប្រភាគ</p><h2>ប្រតិបត្តិ</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គណនាកន្សោម \\(A=\\frac{3}{5}\\times\\left(-\\frac{1}{4}-\\frac{1}{6}\\right)\\div\\left(-2\\frac{1}{3}+1\\frac{1}{4}\\right)\\)</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>គណនា \\(x\\) បើគេដឹងថា \\(\\frac{3}{4}\\div x=2\\) ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">7. វិធីចែកប្រភាគ</p><h2>ចម្លើយ</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គេបាន ៖ \\[\\begin{aligned}\n    A &amp;= \\frac{3}{5}\\times\\left(\\frac{-3-2}{12}\\right)\\div\\left(\\frac{-7}{3}+\\frac{5}{4}\\right) \\\\\n      &amp;= \\frac{3}{5}\\times\\left(-\\frac{5}{12}\\right)\\div\\left(\\frac{-28+15}{12}\\right) \\\\\n      &amp;= \\left(-\\frac{1}{4}\\right)\\div\\left(-\\frac{13}{12}\\right) \\\\\n      &amp;= \\left(-\\frac{1}{4}\\right)\\times\\left(-\\frac{12}{13}\\right) \\\\\n      &amp;= \\frac{3}{13}\n    \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>គេបាន ៖ \\[\\begin{aligned}\n    \\frac{3}{4}\\div x &amp;= 2 \\\\\n    x &amp;= \\frac{3}{4}\\div2 \\\\\n      &amp;= \\frac{3}{4}\\times\\frac{1}{2} \\\\\n      &amp;= \\frac{3}{8}\n    \\end{aligned}\\]</div></li></ul><p>ដូចនេះ ក. \\(A=\\frac{3}{13}\\) ខ. \\(x=\\frac{3}{8}\\) ។</p>"}, {"k": "title", "html": "<p class=\"ts-kicker\">ផ្នែក</p><h1>8. ចំណោទ</h1>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">8. ចំណោទ</p><h2>ឧទាហរណ៍ 1</h2><p>ម្តាយចែកប្រាក់ឱ្យកូន \\(4\\) នាក់ ។ កូនទី \\(1\\) ទទួលបាន \\(\\frac{1}{6}\\) កូនទី \\(2\\) ទទួលបាន \\(\\frac{1}{4}\\) កូនទី \\(3\\) ទទួលបាន \\(\\frac{1}{2}\\) នៃប្រាក់ដែលគាត់បានយកមកចែក និងកូនទី \\(4\\) ទទួលបាន \\(20~000~\\text{៛}\\) ។ តើប្រាក់ដែលគាត់បានចែកឱ្យកូនទាំងអស់មានប៉ុន្មានរៀល?</p><p>ប្រភាគតាងឱ្យប្រាក់ដែលកូនទី \\(1\\) ទី \\(2\\) និងទី \\(3\\) ទទួលបាន \\[\\frac{1}{6}+\\frac{1}{4}+\\frac{1}{2}=\\frac{2+3+6}{12}=\\frac{11}{12}\\] ប្រភាគតាងឱ្យប្រាក់កូនទី \\(4\\) ទទួលបានគឺ \\[1-\\frac{11}{12}=\\frac{1}{12}\\] \\[\\begin{aligned}\n\\frac{1}{12} &amp;\\text{ នៃប្រាក់ដែលគាត់បានចែកស្មើនឹង } 20~000~\\text{៛} \\\\\n\\frac{12}{12} &amp;\\text{ នៃប្រាក់ដែលគាត់បានចែកគឺ } 20~000\\times12=240~000~\\text{៛}\n\\end{aligned}\\] ដូច្នេះប្រាក់ដែលគាត់បានចែកឱ្យកូនទាំងអស់មានចំនួន \\(240~000~\\text{៛}\\) ។</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">8. ចំណោទ</p><h2>ឧទាហរណ៍ 2</h2><p>ម៉ាស៊ីនទី \\(1\\) បូមទឹកដាក់អាងមួយពេញក្នុងរយៈពេល \\(5\\) ម៉ោង ។ ម៉ាស៊ីនមួយទៀតបូមទឹកដាក់អាងនោះពេញក្នុងរយៈពេល \\(6\\) ម៉ោង ។ បើម៉ាស៊ីនទាំងពីរនេះបូមទឹកដាក់អាងព្រមគ្នា តើរយៈពេលប៉ុន្មានទើបទឹកពេញអាង?</p><p>ក្នុង \\(1\\) ម៉ោងម៉ាស៊ីនបូមទឹកទី \\(1\\) បូមទឹកដាក់អាងបាន \\(\\frac{1}{5}\\) ។</p><p>ក្នុង \\(1\\) ម៉ោងម៉ាស៊ីនបូមទឹកទី \\(2\\) បូមទឹកដាក់អាងបាន \\(\\frac{1}{6}\\) ។</p><p>ម៉ាស៊ីនទាំងពីរបូមព្រមគ្នា \\(1\\) ម៉ោងបាន \\[\\frac{1}{5}+\\frac{1}{6}=\\frac{6+5}{30}=\\frac{11}{30} \\text{ នៃអាង}\\] \\[\\begin{aligned}\n\\frac{11}{30} &amp;\\text{ នៃអាងម៉ាស៊ីនទាំងពីរប្រើអស់រយៈពេល } 1 \\text{ ម៉ោង} \\\\\n\\frac{1}{30} &amp;\\text{ នៃអាងម៉ាស៊ីនទាំងពីរប្រើអស់រយៈពេល } \\frac{1}{11} \\text{ ម៉ោង} \\\\\n\\frac{30}{30} &amp;\\text{ នៃអាងម៉ាស៊ីនទាំងពីរប្រើអស់រយៈពេល } \\left(\\frac{1}{11}\\times30\\right)\\text{ ម៉ោង}=\\frac{30}{11}\\text{ ម៉ោង}\n\\end{aligned}\\] ដូច្នេះម៉ាស៊ីនទាំងពីរបូមទឹកដាក់អាងរួមគ្នាប្រើអស់រយៈពេល \\(2\\frac{8}{11}\\) ម៉ោងទើបពេញអាង ។</p>"}, {"k": "ex", "html": "<p class=\"ts-kicker\">8. ចំណោទ</p><h2>ឧទាហរណ៍ 3</h2><p>វិចិត្រទទួលបានប្រាក់ចំណូលសរុប \\(800~000~\\text{៛}\\) ដែល \\(\\frac{3}{4}\\) នៃប្រាក់ចំណូលនេះបានមកពីការងារ ។ គណនាប្រាក់ចំណូលបានមកពីការងាររបស់វិចិត្រ ។ \\[\\text{ប្រាក់ចំណូលពីការងារ} = 800~000~\\text{៛}\\times\\frac{3}{4}=600~000~\\text{៛}\\] ដូច្នេះប្រាក់ចំណូលរបស់វិចិត្របានពីការងារគឺ \\(600~000~\\text{៛}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">8. ចំណោទ</p><h2>លំហាត់គំរូ 1</h2><p>កសិដ្ឋានចិញ្ចឹមសត្វមួយកន្លែងទទួលប្រាក់ចំណូល \\(3~800~000~\\text{៛}\\) ក្នុង \\(1\\) ខែ ។ ក្នុងនោះប្រាក់ចំណូលពីការលក់មាន់ស្មើនឹង \\(\\frac{1}{4}\\) នៃប្រាក់ចំណូលសរុបនិងពីការលក់ជ្រូកស្មើនឹង \\(\\frac{2}{4}\\) ហើយប្រាក់ចំណូលដែលនៅសល់គឺបានពីការលក់ត្រី ។ គណនាប្រាក់ចំណូលពីការលក់ត្រី ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">8. ចំណោទ</p><h2>ដំណោះស្រាយ</h2><p>ប្រភាគតាងឱ្យប្រាក់ចំណូលពីការលក់មាន់និងការលក់ជ្រូក ៖ \\[\\frac{1}{4}+\\frac{2}{4}=\\frac{3}{4}\\] ប្រភាគតាងឱ្យប្រាក់ចំណូលពីការលក់ត្រី ៖ \\[1-\\frac{3}{4}=\\frac{1}{4}\\] ប្រាក់ចំណូលពីការលក់ត្រី ៖ \\[3~800~000~\\text{៛}\\times\\frac{1}{4}=950~000~\\text{៛}\\] ដូច្នេះ ប្រាក់ចំណូលពីការលក់ត្រីគឺ \\(950~000~\\text{៛}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">8. ចំណោទ</p><h2>លំហាត់គំរូ 2</h2><p>\\(\\frac{2}{3}\\) នៃប្រាក់ចំណូលរបស់អ្នកត្រូវបានចំណាយលើតម្រូវការបង់ប្រាក់ផ្សេងៗ ហើយ \\(\\frac{1}{3}\\) នៃប្រាក់ចំណូលសម្រាប់ការសន្សំ ។ បើអ្នកសន្សំបានប្រាក់ \\(300~000~\\text{៛}\\) ក្នុងមួយខែ តើអ្នកទទួលបានប្រាក់ចំណូលប្រចាំខែប៉ុន្មាន?</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">8. ចំណោទ</p><h2>ដំណោះស្រាយ</h2><p>\\[\\begin{aligned}\n\\text{ប្រាក់សន្សំ} &amp;= \\text{ប្រាក់ចំណូល}\\times\\frac{1}{3} \\\\\n\\text{ប្រាក់ចំណូល} &amp;= 300~000~\\text{៛}\\times3 \\\\\n &amp;= 900~000~\\text{៛}\n\\end{aligned}\\] ដូច្នេះប្រាក់ចំណូលប្រចាំខែគឺ \\(900~000~\\text{៛}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">8. ចំណោទ</p><h2>ប្រតិបត្តិ 1</h2><p>ចិន្តាអានសៀវភៅមួយដល់ទំព័រទី \\(377\\) ។ បន្ទាប់មកនាងដឹងថា នាងអានបាន \\(\\frac{13}{15}\\) នៃសៀវភៅនេះ ។ តើសៀវភៅនោះមានចំនួនប៉ុន្មានទំព័រ?</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">8. ចំណោទ</p><h2>ចម្លើយ</h2><p>\\(\\frac{13}{15}\\) នៃសៀវភៅស្មើនឹង \\(377\\) ទំព័រ ។ \\[\\begin{aligned}\n\\text{ចំនួនទំព័រទាំងអស់} &amp;= 377\\div\\frac{13}{15} \\\\\n &amp;= 377\\times\\frac{15}{13} \\\\\n &amp;= 29\\times15 \\\\\n &amp;= 435\n\\end{aligned}\\] ដូចនេះ សៀវភៅនោះមាន \\(435\\) ទំព័រ ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">8. ចំណោទ</p><h2>ប្រតិបត្តិ 2</h2><p>ពូ ស៊ឹមរកប្រាក់ចំណូលបាន \\(900~000~\\text{៛}\\) ក្នុង \\(1\\) ខែពីការរត់តាក់ស៊ី ។ ប្រពន្ធគាត់ជាអ្នកលក់កាហ្វេហើយរកចំណូលក្នុង \\(1\\) ខែបាន \\(\\frac{3}{4}\\) នៃប្រាក់ចំណូលរបស់ពូស៊ឹម ។ គណនាប្រាក់ចំណូលសរុបក្នុង \\(1\\) ខែរបស់ពូស៊ឹមនិងប្រពន្ធគាត់ ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">8. ចំណោទ</p><h2>ចម្លើយ</h2><p>\\[\\begin{aligned}\n\\text{ប្រាក់ចំណូលរបស់ប្រពន្ធ} &amp;= 900~000\\times\\frac{3}{4}=675~000~\\text{៛} \\\\\n\\text{ប្រាក់ចំណូលសរុប} &amp;= 900~000+675~000 \\\\\n &amp;= 1~575~000~\\text{៛}\n\\end{aligned}\\] ដូចនេះ ប្រាក់ចំណូលសរុបគឺ \\(1~575~000~\\text{៛}\\) ។</p>"}, {"k": "title", "html": "<p class=\"ts-kicker\">មេរៀនទី ៤</p><h1>លំហាត់</h1><p class=\"ts-sub\">ប្រភាគ</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ១</h2><p>បំពេញចំនួនក្នុងប្រអប់ខាងក្រោម ៖</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(\\frac{3}{5}=\\frac{\\square}{20}\\)</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(\\frac{\\square}{8}=\\frac{-28}{32}\\)</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>\\(\\frac{3}{4}=\\frac{\\square}{-8}=\\frac{-24}{\\square}=\\frac{21}{\\square}\\) ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(20=5\\times4\\) ដូចនេះគុណភាគយកនឹង \\(4\\) ដែរ ៖ \\[\\frac{3}{5}=\\frac{3\\times4}{5\\times4}=\\frac{12}{20} \\implies \\square=12\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(32=8\\times4\\) ដូចនេះចែកភាគយក \\(-28\\) នឹង \\(4\\) ៖ \\[\\frac{-28}{32}=\\frac{-28\\div4}{32\\div4}=\\frac{-7}{8} \\implies \\square=-7\\]</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>តម្រូវប្រភាគ \\(\\frac{3}{4}\\) ទៅតាមភាគបែង ឬភាគយកនីមួយៗ ៖ \\[\\frac{3}{4}=\\frac{3\\times(-2)}{4\\times(-2)}=\\frac{-6}{-8} \\implies \\square=-6\\] \\[\\frac{3}{4}=\\frac{3\\times(-8)}{4\\times(-8)}=\\frac{-24}{-32} \\implies \\square=-32\\] \\[\\frac{3}{4}=\\frac{3\\times7}{4\\times7}=\\frac{21}{28} \\implies \\square=28\\]</div></li></ul>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ២</h2><p>សម្រួលប្រភាគខាងក្រោម ៖</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(\\frac{6}{9}\\)</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(\\frac{18}{33}\\)</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>\\(\\frac{-84}{196}\\)</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>\\(\\frac{-625}{-1000}\\)</div></li><li class=\"lab\"><span class=\"lb\">ង.</span><div>\\(\\frac{2232}{4464}\\) ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ២</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គេបាន ៖ \\[\\frac{6}{9}=\\frac{6\\div3}{9\\div3}=\\frac{2}{3}\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>គេបាន ៖ \\[\\frac{18}{33}=\\frac{18\\div3}{33\\div3}=\\frac{6}{11}\\]</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>\\(\\text{GCD}(84,196)=28\\) ដូចនេះ \\[\\frac{-84}{196}=\\frac{(-84)\\div28}{196\\div28}=\\frac{-3}{7}\\]</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>គេបាន ៖ \\[\\frac{-625}{-1000}=\\frac{625}{1000}=\\frac{625\\div125}{1000\\div125}=\\frac{5}{8}\\]</div></li><li class=\"lab\"><span class=\"lb\">ង.</span><div>ដោយ \\(4464=2232\\times2\\) នោះ \\[\\frac{2232}{4464}=\\frac{2232\\div2232}{4464\\div2232}=\\frac{1}{2}\\]</div></li></ul>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៣</h2><p>គណនាចំនួន \\(x\\) និង \\(y\\) ខាងក្រោម ៖</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(\\frac{x}{7}=\\frac{6}{21}\\)</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(\\frac{-5}{y}=\\frac{20}{28}\\)</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>\\(x\\cdot\\frac{3}{7}=\\frac{2}{3}\\)</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>\\(x\\div\\frac{8}{11}=\\frac{11}{3}\\) ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៣</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គេបាន ៖ \\[\\begin{aligned}\n        \\frac{x}{7} &amp;= \\frac{6}{21} \\\\\n        x\\times21 &amp;= 7\\times6 \\\\\n        x &amp;= \\frac{42}{21} = 2\n        \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>គេបាន ៖ \\[\\begin{aligned}\n        \\frac{-5}{y} &amp;= \\frac{20}{28} \\\\\n        (-5)\\times28 &amp;= y\\times20 \\\\\n        y &amp;= \\frac{-140}{20} = -7\n        \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>គេបាន ៖ \\[\\begin{aligned}\n        x\\cdot\\frac{3}{7} &amp;= \\frac{2}{3} \\\\\n        x &amp;= \\frac{2}{3}\\div\\frac{3}{7} \\\\\n          &amp;= \\frac{2}{3}\\times\\frac{7}{3} \\\\\n          &amp;= \\frac{14}{9}\n        \\end{aligned}\\]</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>គេបាន ៖ \\[\\begin{aligned}\n        x\\div\\frac{8}{11} &amp;= \\frac{11}{3} \\\\\n        x &amp;= \\frac{11}{3}\\times\\frac{8}{11} \\\\\n          &amp;= \\frac{8}{3}\n        \\end{aligned}\\]</div></li></ul>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៤</h2><p>ប្រៀបធៀបនិងរៀបប្រភាគខាងក្រោម តាមលំដាប់ចុះ ៖</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(\\frac{7}{11}\\), \\(\\frac{5}{6}\\), \\(\\frac{4}{9}\\), \\(\\frac{2}{3}\\)</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(\\frac{1}{2}\\), \\(\\frac{2}{3}\\), \\(\\frac{3}{4}\\), \\(\\frac{7}{8}\\), \\(\\frac{7}{12}\\) ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៤</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(\\text{LCM}(11,6,9,3)=198\\) ៖ \\[\\frac{7}{11}=\\frac{126}{198}, \\quad \\frac{5}{6}=\\frac{165}{198}, \\quad \\frac{4}{9}=\\frac{88}{198}, \\quad \\frac{2}{3}=\\frac{132}{198}\\] ដោយ \\(165&gt;132&gt;126&gt;88\\) នោះ \\[\\frac{5}{6}&gt;\\frac{2}{3}&gt;\\frac{7}{11}&gt;\\frac{4}{9}\\]</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(\\text{LCM}(2,3,4,8,12)=24\\) ៖ \\[\\frac{1}{2}=\\frac{12}{24}, \\quad \\frac{2}{3}=\\frac{16}{24}, \\quad \\frac{3}{4}=\\frac{18}{24}, \\quad \\frac{7}{8}=\\frac{21}{24}, \\quad \\frac{7}{12}=\\frac{14}{24}\\] ដោយ \\(21&gt;18&gt;16&gt;14&gt;12\\) នោះ \\[\\frac{7}{8}&gt;\\frac{3}{4}&gt;\\frac{2}{3}&gt;\\frac{7}{12}&gt;\\frac{1}{2}\\]</div></li></ul>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៥</h2><p>បំពេញសញ្ញា (\\(&lt;\\), \\(&gt;\\)) ក្នុងប្រអប់ខាងក្រោម ៖</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(\\frac{-8}{9}\\square\\frac{-7}{9}\\)</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(\\frac{-1}{3}\\square\\frac{-2}{3}\\)</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>\\(\\frac{3}{7}\\square\\frac{-6}{7}\\)</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>\\(\\frac{-3}{11}\\square\\frac{0}{11}\\) ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៥</h2><p>ភាគបែងដូចគ្នា ដូចនេះប្រៀបធៀបតែភាគយក ៖</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(-8&lt;-7\\) នោះ \\(\\frac{-8}{9}&lt;\\frac{-7}{9}\\)</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(-1&gt;-2\\) នោះ \\(\\frac{-1}{3}&gt;\\frac{-2}{3}\\)</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>\\(3&gt;-6\\) នោះ \\(\\frac{3}{7}&gt;\\frac{-6}{7}\\)</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>\\(-3&lt;0\\) នោះ \\(\\frac{-3}{11}&lt;\\frac{0}{11}\\)</div></li></ul>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៦</h2><p>គណនារួចសម្រួល ៖</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(\\frac{14}{20}+\\frac{7}{20}\\)</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(6\\frac{7}{8}-3\\frac{4}{8}\\)</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>\\(\\frac{7}{-25}+\\frac{-8}{25}\\)</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>\\(-\\left(\\frac{1}{4}\\right)^{2}+\\left(\\frac{2}{3}\\right)^{3}\\)</div></li><li class=\"lab\"><span class=\"lb\">ង.</span><div>\\(\\frac{8}{15}+\\frac{11}{15}+\\frac{7}{15}\\)</div></li><li class=\"lab\"><span class=\"lb\">ច.</span><div>\\(5\\frac{3}{10}-3\\frac{4}{-18}\\)</div></li><li class=\"lab\"><span class=\"lb\">ឆ.</span><div>\\(\\frac{4}{5}+\\left(-\\frac{4}{18}\\right)\\)</div></li><li class=\"lab\"><span class=\"lb\">ជ.</span><div>\\(2\\frac{19}{4}-\\frac{1}{18}+\\frac{61}{72}-\\frac{1}{36}\\) ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៦ <span class=\"ts-pg\">(១/២)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គេបាន ៖ \\[\\frac{14}{20}+\\frac{7}{20}=\\frac{14+7}{20}=\\frac{21}{20}=1\\frac{1}{20}\\]</div></li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ខ.</span><div>គេបាន ៖ \\[\\begin{aligned}\n        6\\frac{7}{8}-3\\frac{4}{8} &amp;= (6-3)+\\frac{7-4}{8} \\\\\n         &amp;= 3\\frac{3}{8} = \\frac{27}{8}\n        \\end{aligned}\\]</div></li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">គ.</span><div>គេបាន ៖ \\[\\begin{aligned}\n        \\frac{7}{-25}+\\frac{-8}{25} &amp;= \\frac{-7}{25}+\\frac{-8}{25} \\\\\n         &amp;= \\frac{-15}{25} \\\\\n         &amp;= \\frac{-3}{5}\n        \\end{aligned}\\]</div></li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>គេបាន ៖ \\[\\begin{aligned}\n        -\\left(\\frac{1}{4}\\right)^{2}+\\left(\\frac{2}{3}\\right)^{3} &amp;= -\\frac{1}{16}+\\frac{8}{27} \\\\\n         &amp;= \\frac{-27}{432}+\\frac{128}{432} \\\\\n         &amp;= \\frac{101}{432}\n        \\end{aligned}\\]</div></li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ង.</span><div>គេបាន ៖ \\[\\begin{aligned}\n        \\frac{8}{15}+\\frac{11}{15}+\\frac{7}{15} &amp;= \\frac{8+11+7}{15} \\\\\n         &amp;= \\frac{26}{15} = 1\\frac{11}{15}\n        \\end{aligned}\\]</div></li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ច.</span><div>គេយក \\(3\\frac{4}{-18}=3+\\frac{4}{-18}=3-\\frac{2}{9}=\\frac{25}{9}\\) ៖ \\[\\begin{aligned}\n        5\\frac{3}{10}-3\\frac{4}{-18} &amp;= \\frac{53}{10}-\\frac{25}{9} \\\\\n         &amp;= \\frac{477}{90}-\\frac{250}{90} \\\\\n         &amp;= \\frac{227}{90} = 2\\frac{47}{90}\n        \\end{aligned}\\]</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៦ <span class=\"ts-pg\">(២/២)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ឆ.</span><div>គេបាន ៖ \\[\\begin{aligned}\n        \\frac{4}{5}+\\left(-\\frac{4}{18}\\right) &amp;= \\frac{4}{5}-\\frac{2}{9} \\\\\n         &amp;= \\frac{36}{45}-\\frac{10}{45} \\\\\n         &amp;= \\frac{26}{45}\n        \\end{aligned}\\]</div></li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ជ.</span><div>គេយក \\(2\\frac{19}{4}=2+\\frac{19}{4}=\\frac{27}{4}\\) ។ ភាគបែងរួម \\(\\text{LCM}(4,18,72,36)=72\\) ៖ \\[\\begin{aligned}\n        2\\frac{19}{4}-\\frac{1}{18}+\\frac{61}{72}-\\frac{1}{36} &amp;= \\frac{486}{72}-\\frac{4}{72}+\\frac{61}{72}-\\frac{2}{72} \\\\\n         &amp;= \\frac{486-4+61-2}{72} \\\\\n         &amp;= \\frac{541}{72} = 7\\frac{37}{72}\n        \\end{aligned}\\]</div></li></ul>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៧</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>តើរយៈពេលណាមួយវែងជាង \\(\\frac{3}{2}\\) ម៉ោង ឬ \\(\\frac{3}{4}\\) ម៉ោង ?</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>តើបន្ទាត់ទាំងពីរនេះណាមួយខ្លីជាង \\(\\frac{7}{10}\\) m ឬ \\(\\frac{3}{4}\\) m ?</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>តើម៉ាសណាមួយធំជាង \\(\\frac{7}{8}\\) kg ឬ \\(\\frac{9}{10}\\) kg ?</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>តើល្បឿនណាមួយតូចជាង \\(\\frac{5}{6}\\) km/h ឬ \\(\\frac{7}{9}\\) km/h ?</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៧</h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(\\frac{3}{2}=\\frac{6}{4}\\) ហើយ \\(\\frac{6}{4}&gt;\\frac{3}{4}\\) ។ ដូចនេះ \\(\\frac{3}{2}\\) ម៉ោង វែងជាង ។</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(\\text{LCM}(10,4)=20\\) ៖ \\[\\frac{7}{10}=\\frac{14}{20}, \\qquad \\frac{3}{4}=\\frac{15}{20}\\] ដោយ \\(14&lt;15\\) ដូចនេះ \\(\\frac{7}{10}\\) m ខ្លីជាង ។</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>\\(\\text{LCM}(8,10)=40\\) ៖ \\[\\frac{7}{8}=\\frac{35}{40}, \\qquad \\frac{9}{10}=\\frac{36}{40}\\] ដោយ \\(35&lt;36\\) ដូចនេះ \\(\\frac{9}{10}\\) kg ធំជាង ។</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>\\(\\text{LCM}(6,9)=18\\) ៖ \\[\\frac{5}{6}=\\frac{15}{18}, \\qquad \\frac{7}{9}=\\frac{14}{18}\\] ដោយ \\(14&lt;15\\) ដូចនេះ \\(\\frac{7}{9}\\) km/h តូចជាង ។</div></li></ul>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៨</h2><p>គណនា រួចសម្រួលលទ្ធផល ៖</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(20\\times\\frac{4}{5}\\)</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(\\frac{7}{11}\\times\\frac{-3}{41}\\times\\frac{11}{7}\\)</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>\\(\\frac{-5}{9}\\times\\frac{13}{28}-\\frac{13}{28}\\times\\frac{4}{9}\\)</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>\\(\\left(-8\\frac{1}{3}\\right)\\times\\left(2\\frac{2}{5}\\right)\\)</div></li><li class=\"lab\"><span class=\"lb\">ង.</span><div>\\(\\frac{9}{28}\\div\\frac{6}{7}\\)</div></li><li class=\"lab\"><span class=\"lb\">ច.</span><div>\\(12\\frac{1}{4}\\div\\left(-\\frac{14}{3}\\right)\\)</div></li><li class=\"lab\"><span class=\"lb\">ឆ.</span><div>\\(\\frac{3}{4}\\div\\left(-\\frac{-2}{3}\\right)^{2}\\) ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៨ <span class=\"ts-pg\">(១/២)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គេបាន ៖ \\[20\\times\\frac{4}{5}=\\frac{20\\times4}{5}=\\frac{80}{5}=16\\]</div></li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ខ.</span><div>គេបាន ៖ \\[\\begin{aligned}\n        \\frac{7}{11}\\times\\frac{-3}{41}\\times\\frac{11}{7} &amp;= \\left(\\frac{7}{11}\\times\\frac{11}{7}\\right)\\times\\frac{-3}{41} \\\\\n         &amp;= 1\\times\\frac{-3}{41} \\\\\n         &amp;= \\frac{-3}{41}\n        \\end{aligned}\\]</div></li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">គ.</span><div>គេបាន ៖ \\[\\begin{aligned}\n        \\frac{-5}{9}\\times\\frac{13}{28}-\\frac{13}{28}\\times\\frac{4}{9} &amp;= \\frac{13}{28}\\times\\left(\\frac{-5}{9}-\\frac{4}{9}\\right) \\\\\n         &amp;= \\frac{13}{28}\\times\\frac{-9}{9} \\\\\n         &amp;= \\frac{13}{28}\\times(-1) \\\\\n         &amp;= \\frac{-13}{28}\n        \\end{aligned}\\]</div></li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>គេបាន ៖ \\[\\begin{aligned}\n        \\left(-8\\frac{1}{3}\\right)\\times\\left(2\\frac{2}{5}\\right) &amp;= \\frac{-25}{3}\\times\\frac{12}{5} \\\\\n         &amp;= -\\frac{25\\times12}{3\\times5} \\\\\n         &amp;= -20\n        \\end{aligned}\\]</div></li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ង.</span><div>គេបាន ៖ \\[\\begin{aligned}\n        \\frac{9}{28}\\div\\frac{6}{7} &amp;= \\frac{9}{28}\\times\\frac{7}{6} \\\\\n         &amp;= \\frac{9\\times7}{28\\times6} \\\\\n         &amp;= \\frac{3}{8}\n        \\end{aligned}\\]</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៨ <span class=\"ts-pg\">(២/២)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ច.</span><div>គេបាន ៖ \\[\\begin{aligned}\n        12\\frac{1}{4}\\div\\left(-\\frac{14}{3}\\right) &amp;= \\frac{49}{4}\\times\\left(-\\frac{3}{14}\\right) \\\\\n         &amp;= -\\frac{49\\times3}{4\\times14} \\\\\n         &amp;= -\\frac{21}{8} = -2\\frac{5}{8}\n        \\end{aligned}\\]</div></li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ឆ.</span><div>ដោយ \\(-\\frac{-2}{3}=\\frac{2}{3}\\) ៖ \\[\\begin{aligned}\n        \\frac{3}{4}\\div\\left(-\\frac{-2}{3}\\right)^{2} &amp;= \\frac{3}{4}\\div\\left(\\frac{2}{3}\\right)^{2} \\\\\n         &amp;= \\frac{3}{4}\\div\\frac{4}{9} \\\\\n         &amp;= \\frac{3}{4}\\times\\frac{9}{4} \\\\\n         &amp;= \\frac{27}{16} = 1\\frac{11}{16}\n        \\end{aligned}\\]</div></li></ul>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ៩</h2><p>គណនា រួចសម្រួល ៖</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>\\(\\left(\\frac{1}{5}-\\frac{1}{2}\\right)\\div\\left(-\\frac{2}{3}\\times\\frac{1}{8}\\right)\\)</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>\\(\\frac{11}{12}\\times\\left(-\\frac{23}{33}+\\frac{7}{11}\\right)\\)</div></li><li class=\"lab\"><span class=\"lb\">គ.</span><div>\\(\\frac{3}{5}\\times\\left(-\\frac{1}{4}-\\frac{1}{6}\\right)\\div\\left(-2\\frac{1}{3}+1\\frac{1}{4}\\right)\\)</div></li><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>\\(\\left(-1\\frac{1}{6}\\times2\\frac{1}{2}\\times1\\frac{3}{5}\\right)\\div\\left[1\\frac{1}{4}\\times\\left(-2\\frac{3}{10}\\right)\\times1\\frac{2}{3}\\right]\\)</div></li><li class=\"lab\"><span class=\"lb\">ង.</span><div>\\(\\left(1\\frac{1}{5}+\\frac{7}{22}\\right)\\div\\left(\\frac{7}{15}+\\frac{2}{5}\\right)\\)</div></li><li class=\"lab\"><span class=\"lb\">ច.</span><div>\\(\\dfrac{5\\frac{3}{4}+2\\frac{2}{3}\\times1\\frac{5}{16}}{\\frac{2}{5}+\\frac{4}{15}}\\)</div></li><li class=\"lab\"><span class=\"lb\">ឆ.</span><div>\\(\\left(\\dfrac{1-\\frac{1}{2}}{1+\\frac{1}{2}}\\times\\dfrac{\\frac{7}{6}-\\frac{1}{3}}{\\frac{4}{3}}\\times\\dfrac{-18}{10}\\right)\\div\\left(\\dfrac{2}{2}\\times\\dfrac{1-\\frac{1}{7}}{1+\\frac{1}{7}}\\right)\\) ។</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៩ <span class=\"ts-pg\">(១/៣)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គេបាន ៖ \\[\\begin{aligned}\n        \\left(\\frac{1}{5}-\\frac{1}{2}\\right)\\div\\left(-\\frac{2}{3}\\times\\frac{1}{8}\\right) &amp;= \\left(\\frac{2-5}{10}\\right)\\div\\left(-\\frac{1}{12}\\right) \\\\\n         &amp;= \\left(-\\frac{3}{10}\\right)\\times(-12) \\\\\n         &amp;= \\frac{18}{5} = 3\\frac{3}{5}\n        \\end{aligned}\\]</div></li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ខ.</span><div>គេបាន ៖ \\[\\begin{aligned}\n        \\frac{11}{12}\\times\\left(-\\frac{23}{33}+\\frac{7}{11}\\right) &amp;= \\frac{11}{12}\\times\\left(-\\frac{23}{33}+\\frac{21}{33}\\right) \\\\\n         &amp;= \\frac{11}{12}\\times\\frac{-2}{33} \\\\\n         &amp;= \\frac{-22}{396} \\\\\n         &amp;= \\frac{-1}{18}\n        \\end{aligned}\\]</div></li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">គ.</span><div>គេបាន ៖ \\[\\begin{aligned}\n        &amp;\\frac{3}{5}\\times\\left(-\\frac{1}{4}-\\frac{1}{6}\\right)\\div\\left(-2\\frac{1}{3}+1\\frac{1}{4}\\right) \\\\\n         &amp;= \\frac{3}{5}\\times\\left(-\\frac{5}{12}\\right)\\div\\left(-\\frac{13}{12}\\right) \\\\\n         &amp;= \\left(-\\frac{1}{4}\\right)\\times\\left(-\\frac{12}{13}\\right) \\\\\n         &amp;= \\frac{3}{13}\n        \\end{aligned}\\]</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៩ <span class=\"ts-pg\">(២/៣)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ឃ.</span><div>គណនាតួទី \\(1\\) និងតួទី \\(2\\) ដោយឡែកពីគ្នា ៖ \\[\\begin{aligned}\n        -1\\frac{1}{6}\\times2\\frac{1}{2}\\times1\\frac{3}{5} &amp;= -\\frac{7}{6}\\times\\frac{5}{2}\\times\\frac{8}{5} \\\\\n         &amp;= -\\frac{7\\times5\\times8}{6\\times2\\times5} = -\\frac{14}{3}\n        \\end{aligned}\\] \\[\\begin{aligned}\n        1\\frac{1}{4}\\times\\left(-2\\frac{3}{10}\\right)\\times1\\frac{2}{3} &amp;= \\frac{5}{4}\\times\\left(-\\frac{23}{10}\\right)\\times\\frac{5}{3} \\\\\n         &amp;= -\\frac{5\\times23\\times5}{4\\times10\\times3} = -\\frac{115}{24}\n        \\end{aligned}\\] \\[\\begin{aligned}\n        \\left(-\\frac{14}{3}\\right)\\div\\left(-\\frac{115}{24}\\right) &amp;= \\frac{14}{3}\\times\\frac{24}{115} \\\\\n         &amp;= \\frac{112}{115}\n        \\end{aligned}\\]</div></li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ង.</span><div>គេបាន ៖ \\[\\begin{aligned}\n        1\\frac{1}{5}+\\frac{7}{22} &amp;= \\frac{6}{5}+\\frac{7}{22} = \\frac{132}{110}+\\frac{35}{110} = \\frac{167}{110} \\\\\n        \\frac{7}{15}+\\frac{2}{5} &amp;= \\frac{7}{15}+\\frac{6}{15} = \\frac{13}{15}\n        \\end{aligned}\\] \\[\\begin{aligned}\n        \\frac{167}{110}\\div\\frac{13}{15} &amp;= \\frac{167}{110}\\times\\frac{15}{13} \\\\\n         &amp;= \\frac{167\\times3}{22\\times13} \\\\\n         &amp;= \\frac{501}{286} = 1\\frac{215}{286}\n        \\end{aligned}\\]</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ៩ <span class=\"ts-pg\">(៣/៣)</span></h2><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ច.</span><div>គណនាភាគយក និងភាគបែងដោយឡែកពីគ្នា ៖ \\[\\begin{aligned}\n        5\\frac{3}{4}+2\\frac{2}{3}\\times1\\frac{5}{16} &amp;= \\frac{23}{4}+\\frac{8}{3}\\times\\frac{21}{16} \\\\\n         &amp;= \\frac{23}{4}+\\frac{7}{2} \\\\\n         &amp;= \\frac{23}{4}+\\frac{14}{4}=\\frac{37}{4}\n        \\end{aligned}\\] \\[\\frac{2}{5}+\\frac{4}{15}=\\frac{6}{15}+\\frac{4}{15}=\\frac{10}{15}=\\frac{2}{3}\\] \\[\\frac{37}{4}\\div\\frac{2}{3}=\\frac{37}{4}\\times\\frac{3}{2}=\\frac{111}{8}=13\\frac{7}{8}\\]</div></li></ul><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ឆ.</span><div>គណនាកត្តានីមួយៗ ៖ \\[\\frac{1-\\frac{1}{2}}{1+\\frac{1}{2}}=\\frac{\\frac{1}{2}}{\\frac{3}{2}}=\\frac{1}{3}, \\qquad \\frac{\\frac{7}{6}-\\frac{1}{3}}{\\frac{4}{3}}=\\frac{\\frac{5}{6}}{\\frac{4}{3}}=\\frac{5}{8}, \\qquad \\frac{-18}{10}=\\frac{-9}{5}\\] \\[\\frac{1-\\frac{1}{7}}{1+\\frac{1}{7}}=\\frac{\\frac{6}{7}}{\\frac{8}{7}}=\\frac{3}{4}\\] \\[\\begin{aligned}\n        \\text{តួទី } 1 &amp;= \\frac{1}{3}\\times\\frac{5}{8}\\times\\frac{-9}{5} = \\frac{-3}{8} \\\\\n        \\text{តួទី } 2 &amp;= \\frac{2}{2}\\times\\frac{3}{4} = \\frac{3}{4}\n        \\end{aligned}\\] \\[\\frac{-3}{8}\\div\\frac{3}{4}=\\frac{-3}{8}\\times\\frac{4}{3}=\\frac{-1}{2}\\]</div></li></ul>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ១០</h2><p>ពិនិត្យលំនាំគំរូ \\[\\frac{1}{1\\times2}=\\frac{1}{1}-\\frac{1}{2}, \\qquad \\frac{1}{2\\times3}=\\frac{1}{2}-\\frac{1}{3}, \\qquad \\frac{1}{3\\times4}=\\frac{1}{3}-\\frac{1}{4}\\] តាមលំនាំគំរូនេះ គណនា \\[\\frac{1}{1\\times2}+\\frac{1}{2\\times3}+\\frac{1}{3\\times4}+\\frac{1}{4\\times5}+\\dots+\\frac{1}{1995\\times1996}\\]</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១០</h2><p>តាមលំនាំគំរូ \\(\\frac{1}{n\\times(n+1)}=\\frac{1}{n}-\\frac{1}{n+1}\\) ដូចនេះ ៖ \\[\\begin{aligned}\n    S &amp;= \\left(\\frac{1}{1}-\\frac{1}{2}\\right)+\\left(\\frac{1}{2}-\\frac{1}{3}\\right)+\\left(\\frac{1}{3}-\\frac{1}{4}\\right)+\\dots+\\left(\\frac{1}{1995}-\\frac{1}{1996}\\right) \\\\\n      &amp;= \\frac{1}{1}-\\frac{1}{2}+\\frac{1}{2}-\\frac{1}{3}+\\frac{1}{3}-\\dots-\\frac{1}{1995}+\\frac{1}{1995}-\\frac{1}{1996} \\\\\n      &amp;= 1-\\frac{1}{1996} \\\\\n      &amp;= \\frac{1995}{1996}\n    \\end{aligned}\\]</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ១១</h2><p>ពិនិត្យលំនាំគំរូ \\[\\frac{1}{1}=\\frac{1}{1}, \\qquad \\frac{1}{2}=\\frac{2}{1+3}, \\qquad \\frac{1}{3}=\\frac{3}{1+3+5}, \\qquad \\frac{1}{4}=\\frac{4}{1+3+5+7}\\] សរសេរប្រភាគ \\(\\frac{1}{5}\\), \\(\\frac{1}{6}\\), \\(\\frac{1}{7}\\) និង \\(\\frac{1}{8}\\) តាមលំនាំគំរូខាងលើ ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១១</h2><p>ភាគយកស្មើនឹងចំនួនតួនៃផលបូកខាងក្រោម ហើយភាគបែងជាផលបូកនៃចំនួនសេសតាមលំដាប់ចាប់ពី \\(1\\) ៖ \\[\\begin{aligned}\n    \\frac{1}{5} &amp;= \\frac{5}{1+3+5+7+9} \\\\\n    \\frac{1}{6} &amp;= \\frac{6}{1+3+5+7+9+11} \\\\\n    \\frac{1}{7} &amp;= \\frac{7}{1+3+5+7+9+11+13} \\\\\n    \\frac{1}{8} &amp;= \\frac{8}{1+3+5+7+9+11+13+15}\n    \\end{aligned}\\] (ផលបូកនៃចំនួនសេស \\(n\\) តួដំបូងស្មើ \\(n^2\\) ដូចនេះ \\(\\frac{n}{n^2}=\\frac{1}{n}\\)) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ១២</h2><p>នៅថ្ងៃចន្ទ សុភ័ក្ត្របានចំណាយអស់ \\(\\frac{7}{24}\\) នៅថ្ងៃអង្គារចំណាយអស់ \\(\\frac{1}{4}\\) នៅថ្ងៃពុធចំណាយអស់ \\(\\frac{1}{3}\\) នៃប្រាក់របស់គាត់ ។ រកប្រភាគតាងប្រាក់របស់សុភ័ក្ត្រដែលនៅសល់សម្រាប់ចំណាយថ្ងៃព្រហស្បតិ៍ ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១២</h2><p>ប្រភាគតាងប្រាក់ដែលចំណាយក្នុងថ្ងៃចន្ទ អង្គារ និងពុធ ៖ \\[\\frac{7}{24}+\\frac{1}{4}+\\frac{1}{3}=\\frac{7}{24}+\\frac{6}{24}+\\frac{8}{24}=\\frac{21}{24}=\\frac{7}{8}\\] ប្រភាគតាងប្រាក់ដែលនៅសល់ ៖ \\[1-\\frac{7}{8}=\\frac{1}{8}\\] ដូចនេះ ប្រាក់ដែលនៅសល់សម្រាប់ចំណាយថ្ងៃព្រហស្បតិ៍ស្មើនឹង \\(\\frac{1}{8}\\) នៃប្រាក់របស់គាត់ ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ១៣</h2><p>តាសានបានលក់គោមួយក្បាលនិងក្របីមួយក្បាលថ្លៃ \\(13~600~000~\\text{៛}\\) ។ ថ្លៃលក់គោស្មើនឹង \\(\\frac{3}{5}\\) នៃថ្លៃលក់ក្របី ។ តើសត្វនីមួយៗលក់ថ្លៃប៉ុន្មាន?</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១៣</h2><p>តាងថ្លៃលក់ក្របីស្មើ \\(5\\) ចំណែក នោះថ្លៃលក់គោស្មើ \\(3\\) ចំណែក ។ ថ្លៃទាំងពីរស្មើ \\(5+3=8\\) ចំណែក ៖ \\[\\begin{aligned}\n    8 \\text{ ចំណែក} &amp;= 13~600~000~\\text{៛} \\\\\n    1 \\text{ ចំណែក} &amp;= 13~600~000\\div8=1~700~000~\\text{៛}\n    \\end{aligned}\\] \\[\\begin{aligned}\n    \\text{ថ្លៃលក់គោ} &amp;= 3\\times1~700~000=5~100~000~\\text{៛} \\\\\n    \\text{ថ្លៃលក់ក្របី} &amp;= 5\\times1~700~000=8~500~000~\\text{៛}\n    \\end{aligned}\\] ពិនិត្យ ៖ \\(5~100~000+8~500~000=13~600~000\\) ហើយ \\(\\frac{5~100~000}{8~500~000}=\\frac{3}{5}\\) ។</p><p>ដូចនេះ គោលក់ \\(5~100~000~\\text{៛}\\) ហើយក្របីលក់ \\(8~500~000~\\text{៛}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ១៤</h2><p>អ្នករកស៊ីហ៊ុនគ្នា \\(3\\) នាក់បានចែកប្រាក់ចំណេញគ្នា ។ អ្នកទី \\(1\\) ទទួលបាន \\(\\frac{2}{5}\\) អ្នកទី \\(2\\) ទទួលបាន \\(\\frac{4}{9}\\) នៃប្រាក់នៅសល់ពីអ្នកទី \\(1\\) ហើយអ្នកទី \\(3\\) ទទួលបាន \\(8~300\\) ដុល្លារ ។ តើចំនួនប្រាក់ដែលបានចែកគ្នានោះមានចំនួនប៉ុន្មាន? ហើយអ្នកទី \\(1\\) និងអ្នកទី \\(2\\) ម្នាក់ៗទទួលបានប៉ុន្មាន?</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១៤</h2><p>តាងប្រាក់ទាំងអស់ដែលបានចែកដោយ \\(T\\) ។ \\[\\begin{aligned}\n    \\text{អ្នកទី } 1 &amp;= \\frac{2}{5}T \\\\\n    \\text{ប្រាក់នៅសល់ពីអ្នកទី } 1 &amp;= 1-\\frac{2}{5}=\\frac{3}{5}T \\\\\n    \\text{អ្នកទី } 2 &amp;= \\frac{4}{9}\\times\\frac{3}{5}T=\\frac{4}{15}T\n    \\end{aligned}\\] ប្រភាគតាងប្រាក់របស់អ្នកទី \\(3\\) ៖ \\[1-\\frac{2}{5}-\\frac{4}{15}=\\frac{15}{15}-\\frac{6}{15}-\\frac{4}{15}=\\frac{5}{15}=\\frac{1}{3}\\] \\[\\begin{aligned}\n    \\frac{1}{3}T &amp;= 8~300 \\\\\n    T &amp;= 8~300\\times3=24~900\n    \\end{aligned}\\] \\[\\begin{aligned}\n    \\text{អ្នកទី } 1 &amp;= \\frac{2}{5}\\times24~900=9~960 \\\\\n    \\text{អ្នកទី } 2 &amp;= \\frac{4}{15}\\times24~900=6~640\n    \\end{aligned}\\] ពិនិត្យ ៖ \\(9~960+6~640+8~300=24~900\\) ។</p><p>ដូចនេះ ប្រាក់ដែលបានចែកគ្នាមាន \\(24~900\\) ដុល្លារ អ្នកទី \\(1\\) ទទួលបាន \\(9~960\\) ដុល្លារ និងអ្នកទី \\(2\\) ទទួលបាន \\(6~640\\) ដុល្លារ ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ១៥</h2><p>ក្នុងថ្នាក់រៀនមួយមានសិស្ស \\(42\\) នាក់ ។ \\(\\frac{3}{4}\\) នៃសិស្សប្រុសនិង \\(\\frac{2}{3}\\) នៃសិស្សស្រី ធ្វើដំណើរទៅសាលាដោយជិះកង់ ។ ចំនួនសិស្សប្រុសនិងសិស្សស្រីធ្វើដំណើរទៅសាលារៀនដោយជិះកង់មានទាំងអស់ \\(30\\) នាក់ ។</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>តើនៅក្នុងថ្នាក់រៀនមានសិស្សប្រុសចំនួនប៉ុន្មាននាក់?</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div>តើសិស្សស្រីធ្វើដំណើរទៅសាលារៀនដោយជិះកង់មានចំនួនប៉ុន្មាននាក់?</div></li></ul>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១៥</h2><p>តាង \\(b\\) ជាចំនួនសិស្សប្រុស នោះចំនួនសិស្សស្រីគឺ \\(42-b\\) ។</p><ul class=\"ts-bullets\"><li class=\"lab\"><span class=\"lb\">ក.</span><div>គេបាន ៖ \\[\\begin{aligned}\n        \\frac{3}{4}b+\\frac{2}{3}(42-b) &amp;= 30 \\\\\n        \\frac{9b}{12}+\\frac{8(42-b)}{12} &amp;= \\frac{360}{12} \\\\\n        9b+336-8b &amp;= 360 \\\\\n        b &amp;= 24\n        \\end{aligned}\\] ដូចនេះ នៅក្នុងថ្នាក់រៀនមានសិស្សប្រុស \\(24\\) នាក់ ។</div></li><li class=\"lab\"><span class=\"lb\">ខ.</span><div><p>ចំនួនសិស្សស្រី \\(=42-24=18\\) នាក់ ។ \\[\\text{សិស្សស្រីជិះកង់}=\\frac{2}{3}\\times18=12 \\text{ នាក់}\\] ពិនិត្យ ៖ សិស្សប្រុសជិះកង់ \\(\\frac{3}{4}\\times24=18\\) នាក់ ហើយ \\(18+12=30\\) ។</p><p>ដូចនេះ សិស្សស្រីធ្វើដំណើរទៅសាលាដោយជិះកង់មាន \\(12\\) នាក់ ។</p></div></li></ul>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ១៦</h2><p>នៅក្នុងប្រអប់មួយមានប៊ិកនិងហ្វឺត \\(53\\) ដើម ។ \\(\\frac{5}{7}\\) នៃប៊ិកនិង \\(\\frac{3}{5}\\) នៃហ្វឺតមានពណ៌ខៀវ ។ ចំនួនប៊ិកនិងហ្វឺតពណ៌ខៀវទាំងអស់មាន \\(35\\) ដើម ។ តើនៅក្នុងប្រអប់នោះមានហ្វឺតប៉ុន្មានដើម?</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១៦</h2><p>តាង \\(p\\) ជាចំនួនប៊ិក នោះចំនួនហ្វឺតគឺ \\(53-p\\) ។ \\[\\begin{aligned}\n    \\frac{5}{7}p+\\frac{3}{5}(53-p) &amp;= 35 \\\\\n    \\frac{25p}{35}+\\frac{21(53-p)}{35} &amp;= \\frac{1~225}{35} \\\\\n    25p+1~113-21p &amp;= 1~225 \\\\\n    4p &amp;= 112 \\\\\n    p &amp;= 28\n    \\end{aligned}\\] ចំនួនហ្វឺត \\(=53-28=25\\) ដើម ។</p><p>ពិនិត្យ ៖ \\(\\frac{5}{7}\\times28=20\\) ហើយ \\(\\frac{3}{5}\\times25=15\\) នោះ \\(20+15=35\\) ។</p><p>ដូចនេះ នៅក្នុងប្រអប់មានហ្វឺត \\(25\\) ដើម ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ១៧</h2><p>គេលក់ដីមួយកន្លែងលើកទី \\(1\\) អស់ \\(\\frac{1}{3}\\) នៃផ្ទៃដីទាំងមូល លើកទី \\(2\\) លក់អស់ \\(\\frac{3}{7}\\) នៃផ្ទៃដីនៅសល់ ហើយដីនោះនៅសល់ \\(58\\) ហិកតាទៀត ។ តើដីនោះមានផ្ទៃក្រឡាប៉ុន្មានហិកតា?</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១៧</h2><p>ផ្ទៃដីនៅសល់ក្រោយលក់លើកទី \\(1\\) ៖ \\[1-\\frac{1}{3}=\\frac{2}{3}\\] ផ្ទៃដីលក់លើកទី \\(2\\) ៖ \\[\\frac{3}{7}\\times\\frac{2}{3}=\\frac{2}{7}\\] ផ្ទៃដីនៅសល់ក្រោយលក់លើកទី \\(2\\) ៖ \\[1-\\frac{1}{3}-\\frac{2}{7}=\\frac{21}{21}-\\frac{7}{21}-\\frac{6}{21}=\\frac{8}{21}\\] \\[\\begin{aligned}\n    \\frac{8}{21} \\text{ នៃផ្ទៃដីទាំងមូល} &amp;= 58 \\text{ ហិកតា} \\\\\n    \\text{ផ្ទៃដីទាំងមូល} &amp;= 58\\div\\frac{8}{21} \\\\\n     &amp;= 58\\times\\frac{21}{8} \\\\\n     &amp;= \\frac{609}{4} = 152{,}25 \\text{ ហិកតា}\n    \\end{aligned}\\] ដូចនេះ ដីនោះមានផ្ទៃក្រឡា \\(152{,}25\\) ហិកតា ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ១៨</h2><p>អ្នកលក់ម្នាក់រកបានប្រាក់ចំណូលសរុប \\(7\\) លានរៀល ពីការលក់សត្វ \\(3\\) ប្រភេទគឺមាន់ ទា និងជ្រូក ។ គេដឹងថាប្រាក់ចំណូលបានពីការលក់មាន់ស្មើ \\(\\frac{1}{4}\\) នៃប្រាក់ចំណូលសរុប ។ គណនាប្រាក់ចំណូលបានពីការលក់មាន់ ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១៨</h2><p>\\[\\begin{aligned}\n    \\text{ប្រាក់ចំណូលពីការលក់មាន់} &amp;= 7~000~000\\times\\frac{1}{4} \\\\\n     &amp;= 1~750~000~\\text{៛}\n    \\end{aligned}\\] ដូចនេះ ប្រាក់ចំណូលបានពីការលក់មាន់គឺ \\(1~750~000~\\text{៛}\\) ។</p>"}, {"k": "prac", "html": "<p class=\"ts-kicker\">លំហាត់</p><h2>លំហាត់ទី ១៩</h2><p>គ្រួសារមួយធ្វើការងារ \\(3\\) នាក់ បានប្រាក់ចំណូលសរុបបាន \\(650~000~\\text{៛}\\) ក្នុងមួយសប្តាហ៍ ។ ឪពុកនិងម្តាយរកបាន \\(\\frac{3}{4}\\) នៃប្រាក់ចំណូលសរុប ។ រកប្រាក់ចំណូលរបស់សមាជិកម្នាក់ទៀតរួចសរសេរប្រភាគនៃប្រាក់ចំណូលនោះធៀបនឹងប្រាក់ចំណូលសរុប ។</p>"}, {"k": "sol", "html": "<p class=\"ts-kicker\">ចម្លើយ</p><h2>ដំណោះស្រាយ លំហាត់ទី ១៩</h2><p>\\[\\begin{aligned}\n    \\text{ឪពុកនិងម្តាយរកបាន} &amp;= 650~000\\times\\frac{3}{4}=487~500~\\text{៛} \\\\\n    \\text{សមាជិកម្នាក់ទៀតរកបាន} &amp;= 650~000-487~500=162~500~\\text{៛}\n    \\end{aligned}\\] ប្រភាគនៃប្រាក់ចំណូលរបស់សមាជិកម្នាក់ទៀតធៀបនឹងប្រាក់ចំណូលសរុប ៖ \\[\\frac{162~500}{650~000}=\\frac{1}{4} \\qquad \\left(\\text{ឬ } 1-\\frac{3}{4}=\\frac{1}{4}\\right)\\] ដូចនេះ សមាជិកម្នាក់ទៀតរកបាន \\(162~500~\\text{៛}\\) ស្មើនឹង \\(\\frac{1}{4}\\) នៃប្រាក់ចំណូលសរុប ។</p>"}, {"k": "title", "html": "<p class=\"ts-kicker\">មេរៀនទី ៤</p><h1>ចប់មេរៀន</h1><p class=\"ts-sub\">ប្រភាគ</p>"}];
